import{soulEffects,soulCategory,soulUse,soulBonus}from'./soul-info.js';import{asiaHeroes}from'./regions.js';import{heroPlan}from'./catalogue-plans.js';
export function renderSoulDetail(catalogue,id,ui){const s=catalogue.souls.find(s=>s.id===id);if(!s)return;const{esc:e,imageTag,minis,inlineGuide,showDetail}=ui,category=soulCategory(id),u=soulUse[category],specialRoles={35:'support',37:'support',38:'support',62:'control',67:'support',68:'support',69:'shield',70:'accelerator'},role=specialRoles[id]||u.role;const candidates=asiaHeroes(catalogue.heroes).filter(h=>h.rarity!=='N'&&heroPlan(h).role===role&&(id!==30||heroPlan(h).needsCrit)).slice(0,10);const supported=[18,24,30,32].includes(id);
showDetail(`<div class="detailhead">${imageTag(s)}<div><span class="eyebrow">御魂資料</span><h2>${e(s.name)}</h2><small>${e(s.en)}</small></div></div><div class="detailbody"><div class="recordstatus"><span class="tag">${category==='monster'?'首領／特殊御魂':'一般四件套御魂'}</span><span class="tag">效果摘要已整理</span><span class="tag">${supported?'有簡化傷害模型':'未納入完整戰鬥模擬'}</span></div><h3>套裝效果</h3><p class="soulbonus">${e(soulBonus(s))}</p><div class="effectsummary"><b>${category==='monster'?'特殊兩件套效果':'四件套效果'}</b><p>${e(soulEffects[id]||'來源新增條目，效果摘要尚需補入，請查閱原始來源。')}</p></div><p class="hint">以上為來源效果的摘要，不是亞洲版當前規則已完成逐項核驗。獨有效果、疊加、免疫及觸發時點以遊戲說明為準；摘要不等於已實作戰鬥模擬。</p><h3>副屬性及用途方向</h3><p>${e(u.subs)}</p><p>套裝名稱不會決定每顆的主屬性。先按實際式神技能選用途，再依六位置規則挑選；以下只是該用途的起點。</p>${inlineGuide(role,s.name+'（按用途選裝）')}<h3>缺少這套時的後備</h3><p>${e(u.fallback)}</p><h3>相近用途的式神候選</h3>${minis(candidates,'hero')}<p class="hint">候選由來源定位與配魂起點篩選，尚未驗證每個技能都能觸發本套；不是最強排名或固定陣容。</p>${supported?'<button class="outline" id="goTest">前往簡易傷害比較 ↗</button>':''}<p><a href="https://guidemyoji.com/souls" target="_blank" rel="noopener">查閱御魂效果來源 ↗</a> · 整理日期：2026-11-15</p></div>`)}
